import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int MOD = sc.nextInt();

        int[] DP = new int[N];
        DP[0] = 1;
        int[] Cum = new int[N + 1];
        Cum[1] = 1;

        for (int i = 1; i < N; i++) {
            int i2 = N - i;
            long val = Cum[i];
            int j = 2;
            while (j <= N) {
                if (i2 * j > N) {
                    break;
                }
                int startIndex = N - i2 * j + 1;
                int endIndex = Math.max(0, N - i2 * j - j + 1);
                val += Cum[startIndex] - Cum[endIndex];
                val %= MOD;
                j++;
            }
            Cum[i + 1] = (Cum[i] + (int) val) % MOD;
            DP[i] = (int) val;
        }
        System.out.println(DP[N - 1]);
        sc.close();
    }
}
